import pytest

from docich.hanjuku_speedrun import hanjuku_reference as reference
from docich.hanjuku_speedrun import hanjuku_policy as p
from docich.hanjuku_speedrun.hanjuku.flows import battle as flow
from docich.hanjuku_speedrun.hanjuku.judgment import battle as rules
from docich.hanjuku_speedrun.hanjuku_screen import Battle, Screen


def memory(ally='クミン', enemy='ヘーゼル', *, ally_hp=40, enemy_hp=100,
           soldiers=(2, 4), egg=None, **cur):
    mem = {'chapter': 1, 'tick': 5, 'battle': {
        'enemy': enemy, 'ally': ally, 'enemy_hp': enemy_hp, 'ally_hp': ally_hp,
        'start_enemy_hp': enemy_hp, 'start_ally_hp': ally_hp,
        'ally_soldiers': soldiers[0], 'enemy_soldiers': soldiers[1],
        'card_soldiers_current': True, 'side': 'attack', 'step': 'S1',
        'castle': 'ゴーメン', 'cards_used': [], 'cards_selected': [],
        'cards_unclassified': [], 'card_evidence_version': 1,
        'planned_cards': [], 'tactics_done': [], 'strategy_expected': None,
        'context': 'message'}}
    if egg is not None:
        mem['egg_uses'] = {ally: egg}
    mem['battle'].update(cur)
    return mem


def screen(mem):
    cur = mem['battle']
    return Screen([], None, '', kind='battle', battle=Battle(
        cur['enemy'], cur['enemy_hp'], cur['ally'], cur['ally_hp']),
        field_soldiers=(cur['ally_soldiers'], cur['enemy_soldiers']))


def combat(name):
    return reference.general_strength(name)[1]


def test_the_score_multiplies_combat_current_hp_and_current_soldiers():
    mem = memory(ally_hp=40, enemy_hp=100, soldiers=(2, 4))
    ours, theirs = rules._melee_product_scores(mem['battle'])
    assert ours == combat('クミン') * 40 * 2
    assert theirs == combat('ヘーゼル') * 100 * 4


def test_zero_soldiers_counts_as_the_general_alone():
    mem = memory(soldiers=(0, 0))
    ours, theirs = rules._melee_product_scores(mem['battle'])
    assert ours == combat('クミン') * mem['battle']['ally_hp']
    assert theirs == combat('ヘーゼル') * mem['battle']['enemy_hp']


def test_unread_or_stale_army_never_produces_a_score():
    mem = memory()
    mem['battle']['card_soldiers_current'] = False
    assert rules._melee_product_scores(mem['battle']) == (None, None)
    assert rules._score_pressure(mem, mem['battle']) is False


@pytest.mark.parametrize('changes,expected', [
    ({}, True),                                                    # 160 vs 1600
    ({'ally_hp': 45, 'soldiers': (6, 0), 'enemy_hp': 100}, False),  # 540 vs 400
])
def test_score_pressure_fires_only_when_our_score_is_lower(changes, expected):
    mem = memory(**changes)
    assert rules._score_pressure(mem, mem['battle']) is expected


@pytest.mark.parametrize('changes', [
    {'enemy': 'クイーン'}, {'egg_battle': True}, {'card_summon_observed': True},
    {'event_duel': True}, {'side': None}, {'ally_hp': 45, 'egg': 2},
    {'enemy_hp': 1},                       # owner 2026-11-25: HP1は資源を温存
])
def test_boss_summon_duel_hp1_and_the_egg_first_general_keep_their_own_rules(changes):
    mem = memory(**changes)
    assert rules._score_pressure(mem, mem['battle']) is False


def test_a_control_card_is_licensed_by_the_score_but_not_when_ahead():
    behind = memory()
    gate = rules._card_damage_gate(behind, behind['battle'], 'クースカン',
                                   listed_cards=['クースカン'])
    assert gate['allowed'] is True and gate['role'] == 'score_pressure_not_a_kill'

    ahead = memory(ally_hp=45, enemy_hp=100, soldiers=(6, 0))
    refused = rules._card_damage_gate(ahead, ahead['battle'], 'クースカン',
                                      listed_cards=['クースカン'])
    assert refused['allowed'] is False
    assert refused['role'] == 'control_has_no_observed_followup'


def _charted_card(monkeypatch, *, kit_known=True, card='クースカン'):
    monkeypatch.setattr(flow, '_tactics', lambda _mem, _step: ({
        'enemy': 'ヘーゼル', 'card': card, 'when_hp_at_most': 5,
        'step': 'S1', 'tactic_id': 'score-test', 'note': 'テスト札'},))
    monkeypatch.setattr(flow, '_egg_drop_tactics', lambda *a, **k: [])
    monkeypatch.setattr(flow, '_strong_card_tactics', lambda *a, **k: [])
    monkeypatch.setattr(flow, '_carried_opening_tactics', lambda *a, **k: [])
    monkeypatch.setattr(flow, '_egg_plan', lambda _mem, _cur: {
        'kit_known': kit_known, 'kit_source': 'order', 'dropper': None,
        'cards': [{'name': card, 'available': 1 if kit_known else None}]})


def test_the_charted_health_timing_is_overridden_only_when_the_score_is_behind(monkeypatch):
    mem = memory()
    _charted_card(monkeypatch)
    assert p.battle_step(screen(mem), mem) == [p.pad('b')]
    cur = mem['battle']
    assert cur['card_flow']['card'] == 'クースカン'
    assert '総合戦力で劣勢' in cur['card_flow']['note']
    planned = [r for r in mem['_records'] if r['decision'] == 'battle_card']
    assert planned and planned[-1]['card_pressure'] == '総合戦力で劣勢'

    ahead = memory(ally_hp=45, enemy_hp=100, soldiers=(6, 0))
    _charted_card(monkeypatch)
    p.battle_step(screen(ahead), ahead)
    assert not (ahead['battle'].get('card_flow') or {}).get('card')


def test_the_opening_egg_drop_still_opens_first_under_the_score_pressure(monkeypatch):
    mem = memory()
    monkeypatch.setattr(flow, '_tactics', lambda _mem, _step: ({
        'enemy': 'ヘーゼル', 'card': 'グリンボー', 'when_hp_at_most': 5,
        'step': 'S1', 'tactic_id': 'score-test', 'note': 'ダメージ札'},))
    monkeypatch.setattr(flow, '_carried_opening_tactics', lambda *a, **k: [])
    monkeypatch.setattr(flow, '_strong_card_tactics', lambda *a, **k: [])
    monkeypatch.setattr(flow, '_egg_plan', lambda _mem, _cur: {
        'kit_known': True, 'kit_source': 'order', 'dropper': 'ブラッキー',
        'cards': [{'name': 'ブラッキー', 'available': 1},
                  {'name': 'グリンボー', 'available': 1}]})
    assert p.battle_step(screen(mem), mem) == [p.pad('b')]
    flow_step = mem['battle']['card_flow']
    assert flow_step['card'] == 'ブラッキー'
    assert flow_step['tactic_id'].startswith('eggdrop:')
